Here's a complete C# MCP server wrapping a REST API with stdio transport.

---

### **Program.cs** — stdio transport with DI
```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: log to stderr only — stdout is the JSON-RPC protocol channel
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient("api", client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();
```

---

### **ApiTools.cs** — tool class with constructor injection
```csharp
using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a user by their unique ID.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var client = httpFactory.CreateClient("api");
        return await client.GetStringAsync($"/users/{userId}", cancellationToken);
    }

    [McpServerTool, Description("Search users by name. Returns matching results.")]
    public async Task<string> SearchUsers(
        [Description("Partial or full name to search for")] string query,
        [Description("Max results to return (1-50)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching users: {Query}", query);
        var client = httpFactory.CreateClient("api");
        var response = await client.GetStringAsync(
            $"/users?q={Uri.EscapeDataString(query)}&limit={limit}",
            cancellationToken);
        return response;
    }

    [McpServerTool(ReadOnly = false, Destructive = false),
     Description("Create a new user with the given name and email.")]
    public async Task<string> CreateUser(
        [Description("Full name of the user")] string name,
        [Description("Email address")] string email,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var payload = JsonSerializer.Serialize(new { name, email });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");
        var response = await client.PostAsync("/users", content, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

---

### How DI works for MCP tools

The SDK supports **two injection styles**:

| Style | Class type | How services are resolved |
|-------|-----------|--------------------------|
| **Constructor injection** | Non-static class | Services injected via primary constructor (like above). The class is instantiated per-call by the DI container. |
| **Method parameter injection** | Static class | DI services appear as method parameters alongside tool parameters. |

**Key rule:** The SDK automatically distinguishes tool parameters from injected services. Types registered in DI (`HttpClient`, `ILogger<T>`, `IHttpClientFactory`, etc.) and framework types (`CancellationToken`, `IMcpServer`, `IProgress<T>`) are **injected automatically** and **never appear** in the tool's JSON schema sent to the LLM. Only parameters with `[Description]` are exposed.

So in `GetUser` above, the LLM sees only `userId` — not the logger, HttpClient, or CancellationToken.

---

### Scaffold this yourself

```bash
dotnet new mcpserver -n MyApiServer
cd MyApiServer
dotnet build && dotnet run
```

Requires .NET 10+ and `dotnet new install Microsoft.McpServer.ProjectTemplates`.
